// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, address recipient) public {
        vm.assume(caller != address(0));
        vm.assume(recipient != address(0));
        vm.deal(address(c), 1 ether);

        uint256 balanceBefore = address(c).balance;
        uint256 recipientBalanceBefore = recipient.balance;

        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.withdrawAll.selector, recipient));

        bool reverted = !success;
        assertTrue((caller == c.owner()) == (!reverted && balanceBefore > 0));
    }
}
